assertions.check:
command -v dotnet >/dev/null || { echo 'FAIL: dotnet SDK not found on PATH'; exit 1; }
d=$(mktemp -d) && trap 'rm -rf "$d"' 0 || exit 1
export DOTNET_CLI_TELEMETRY_OPTOUT=1 DOTNET_NOLOGO=1 DOTNET_SKIP_FIRST_TIME_EXPERIENCE=1
mkdir "$d/src" && cp -R LogParse/. "$d/src/" || exit 1
rm -rf "$d/src/Program.cs" "$d/src/bin" "$d/src/obj"
find "$d/src" -mindepth 2 -name '*.csproj' | while read -r p; do rm -rf "$(dirname "$p")"; done
grep -rlE 'using (BenchmarkDotNet|Xunit|NUnit|Microsoft\.VisualStudio\.TestTools)|\[(Fact|Test|Benchmark)\]' "$d/src" --include='*.cs' | while read -r f; do rm -f "$f"; done
cat > "$d/ZzEval.csproj" <<'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net10.0</TargetFramework>
    <ImplicitUsings>enable</ImplicitUsings>
    <Nullable>enable</Nullable>
    <AllowUnsafeBlocks>true</AllowUnsafeBlocks>
    <EnableDefaultCompileItems>false</EnableDefaultCompileItems>
  </PropertyGroup>
  <ItemGroup>
    <Compile Include="src/**/*.cs" />
    <Compile Include="ZzEval.cs" />
  </ItemGroup>
</Project>
EOF
cat > "$d/ZzEval.cs" <<'EOF'
using System.Globalization;
using LogParse;

namespace ZzEval;

static class Baseline
{
    public static LogEntry Parse(string line)
    {
        string[] parts = line.Split('|');
        if (parts.Length < 4)
            throw new FormatException("expected at least 4 '|'-separated fields");
        long timestamp = long.Parse(parts[0], CultureInfo.InvariantCulture);
        LogLevel level = parts[1] switch
        {
            "DEBUG" => LogLevel.Debug,
            "INFO" => LogLevel.Info,
            "WARN" => LogLevel.Warn,
            "ERROR" => LogLevel.Error,
            _ => throw new FormatException("unknown level: " + parts[1]),
        };
        if (!parts[3].StartsWith("code=E", StringComparison.Ordinal))
            throw new FormatException("missing code field");
        int code = int.Parse(parts[3].Substring(6), CultureInfo.InvariantCulture);
        return new LogEntry(timestamp, level, code);
    }
}

static class Program
{
    static string Outcome(Func<string, LogEntry> parse, string line)
    {
        try { return parse(line).ToString(); }
        catch (Exception e) { return e.GetType().FullName!; }
    }

    static long BytesPerCall(Func<string, LogEntry> parse, string[] lines)
    {
        long sink = 0;
        for (int r = 0; r < 100; r++) foreach (var l in lines) sink += parse(l).Code;
        long before = GC.GetAllocatedBytesForCurrentThread();
        for (int r = 0; r < 200; r++) foreach (var l in lines) sink += parse(l).Code;
        long after = GC.GetAllocatedBytesForCurrentThread();
        GC.KeepAlive(sink);
        return (after - before) / (200L * lines.Length);
    }

    static int Main(string[] args)
    {
        string[] cases =
        {
            "1700000000|INFO|svc=api|code=E404|done", "", "|||", "1|INFO|s|code=E1", "1|INFO|s",
            " 42 |WARN|s|code=E7|x", "-5|DEBUG||code=E-3|", "x|INFO|s|code=E1|m",
            "99999999999999999999|INFO|s|code=E1|m", "1|info|s|code=E1|m", "1|ERROR|s|code=X1|m",
            "1|ERROR|s|code=E|m", "1|ERROR|s|code=E2147483648|m", "1|ERROR|s|code=E12|m|extra|fields",
            "1|ERROR|s|code=E١٢|m", "1|INFO|s|code=E+5|m", "1|INFO|s|code=e5|m", "1|WARN |s|code=E5|m",
        };
        if (args[0] == "equiv")
        {
            int bad = 0;
            foreach (var c in cases)
            {
                string want = Outcome(Baseline.Parse, c), got = Outcome(LogLineParser.Parse, c);
                if (want != got) { Console.WriteLine($"MISMATCH {c}: got {got}, want {want}"); bad++; }
            }
            Console.WriteLine($"equivalence cases={cases.Length} mismatches={bad}");
            return bad == 0 ? 0 : 1;
        }
        var lines = new string[512];
        for (int i = 0; i < lines.Length; i++)
            lines[i] = $"{1_700_000_000 + i}|{(i % 7 == 0 ? "ERROR" : "INFO")}|svc=api-{i % 13}|code=E{i % 600}|request finished in {i % 97} ms";
        long baseBytes = BytesPerCall(Baseline.Parse, lines), candBytes = BytesPerCall(LogLineParser.Parse, lines);
        Console.WriteLine($"allocated bytes per Parse: baseline {baseBytes}, candidate {candBytes}");
        return candBytes * 4 <= baseBytes ? 0 : 1;
    }
}
EOF
dotnet build "$d/ZzEval.csproj" -c Release -nologo -v q -o "$d/out" > "$d/build.log" 2>&1 || { tail -20 "$d/build.log"; exit 1; }
dotnet "$d/out/ZzEval.dll" equiv

